def transform(grid):
    """Join aligned foreground components by the shortest straight bridges (color 2)."""
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    labels = [[-1] * w for _ in range(h)]
    comps = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or labels[r][c] >= 0:
                continue
            q = deque([(r, c)])
            labels[r][c] = comps
            while q:
                y, x = q.popleft()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and labels[yy][xx] < 0:
                        labels[yy][xx] = comps
                        q.append((yy, xx))
            comps += 1
    if comps < 2:
        return [row[:] for row in grid]
    edges = []
    # Scan horizontal then vertical consecutive foreground pairs.
    for r in range(h):
        pts = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(pts, pts[1:]):
            u, v = labels[r][a], labels[r][b]
            if u != v and b > a + 1:
                edges.append((b-a-1, 0, r, a, u, v, [(r, c) for c in range(a+1,b)]))
    for c in range(w):
        pts = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(pts, pts[1:]):
            u, v = labels[a][c], labels[b][c]
            if u != v and b > a + 1:
                edges.append((b-a-1, 1, a, c, u, v, [(r, c) for r in range(a+1,b)]))
    edges.sort(key=lambda e: e[:4])
    parent = list(range(comps))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    out = [row[:] for row in grid]
    for _, _, _, _, u, v, cells in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            for r, c in cells:
                out[r][c] = 2
    return out
